class stringx { char data[8]; public: stringx(); stringx(const stringx&); ~stringx(); };
union color32 { unsigned value; };
class Font { public: enum HORIZJUST { HORIZJUST_LEFT, HORIZJUST_CENTER }; enum VERTJUST { VERTJUST_TOP, VERTJUST_CENTER }; };
class FEMenuSystem; class FEMenuEntry;
void* operator new(unsigned, unsigned, const char*, int);
#define NEW new(0,__FILE__,__LINE__)
class FEMenu { char data0[0x34]; public: float scale_high; char data1[4]; int flags; char data2[0x34]; protected: enum { HF_SELECT=0x10, HF_BACK=0x20 }; public: FEMenu(); void cons(FEMenuSystem*,int,int,color32,color32,color32,float=1.0f,float=1.2f,int=0,int=8); void Add(FEMenuEntry*); void SetHelpText(unsigned); virtual ~FEMenu(); };
class FEMenuEntry { char data[0x60]; public: FEMenuEntry(stringx,FEMenu*,bool=false,Font*=0); };
class BoxText { char data[0xC0]; public: BoxText(Font*,stringx,float,float,int,float,Font::HORIZJUST,Font::VERTJUST,color32,int=0); void makeBox(int,int,bool=false,float=-1.0f,int=-1); };
class FEManager { public: color32 white; }; extern FEManager frontendmanager;
class PauseMenuSystem : public FEMenuSystem { char data[0x34]; public: Font* font; };
extern stringx ksGlobalTextArray[];
enum { GT_MENU_QUIT_CONFIRM=8, GT_FE_MENU_YES=0, GT_FE_MENU_NO=1, FEMENU_WRAP=2 };
class QuitConfirmMenuClass : public FEMenu { PauseMenuSystem *sys; BoxText *question; FEMenuEntry *yesEntry; FEMenuEntry *noEntry; public: QuitConfirmMenuClass(FEMenuSystem*,int,int,color32,color32,color32); virtual ~QuitConfirmMenuClass(); virtual void Draw(); virtual void Select(int); virtual void OnActivate(); };
QuitConfirmMenuClass::QuitConfirmMenuClass(FEMenuSystem* m, int x, int y, color32 c, color32 ch, color32 cha)
{
	FEMenu::cons(m, x, y, c, ch, cha);
	sys = (PauseMenuSystem*) m;

	yesEntry = NEW FEMenuEntry(ksGlobalTextArray[GT_FE_MENU_YES], this);
	Add(yesEntry);
	noEntry = NEW FEMenuEntry(ksGlobalTextArray[GT_FE_MENU_NO], this);
	Add(noEntry);

	question = NEW BoxText(sys->font, ksGlobalTextArray[GT_MENU_QUIT_CONFIRM], 320, 140, 0, 1.0f, Font::HORIZJUST_CENTER, Font::VERTJUST_CENTER, frontendmanager.white, 10);
	question->makeBox(300, 200);

	SetHelpText(HF_SELECT | HF_BACK);
	flags |= FEMENU_WRAP;
	scale_high = 1.0f;
}
